create table app_user (id uuid not null, sub varchar(255) not null, primary key (id));
create table listen (sec_played integer not null, timestamp timestamp(6) with time zone not null, id uuid not null, song_id uuid not null, user_id uuid not null, primary key (id));
create table outbox_event (retry_count integer not null, created_at timestamp(6) with time zone not null, next_attempt_at timestamp(6) with time zone not null, processing_started_at timestamp(6) with time zone, published_at timestamp(6) with time zone, id uuid not null, aggregate_id varchar(255) not null, event_type varchar(255) not null, last_error varchar(255), status varchar(255) not null check ((status in ('PENDING','PROCESSING','PUBLISHED','FAILED'))), topic varchar(255) not null, payload jsonb not null, primary key (id));
create table playlist (amount_likes integer not null, number_of_entries integer not null, version integer not null, creation_timestamp timestamp(6) with time zone not null, total_duration_sec bigint not null, creator_id uuid not null, id uuid not null, name varchar(255) not null, visibility varchar(255) not null check ((visibility in ('PUBLIC','PRIVATE','UNLISTED'))), primary key (id));
create table playlist_entry (song_duration_sec integer not null, position bigint not null, id uuid not null, playlist_id uuid not null, song_id uuid not null, primary key (id));
create table playlist_like (id uuid not null, playlist_id uuid not null, user_id uuid not null, primary key (id), constraint uk_playlist_app_user unique (playlist_id, user_id));
create table processed_event (processed_at timestamp(6) with time zone not null, id uuid not null, aggregate_id varchar(255) not null, event_type varchar(255) not null, primary key (id));
create table song (duration_sec integer, artist_owner_id uuid, id uuid not null, artist_owner_name varchar(255), title varchar(255), primary key (id));
create table song_like (id uuid not null, song_id uuid not null, user_id uuid not null, primary key (id), constraint uk_song_app_user unique (song_id, user_id));
create index idx_listen_user_song_timestamp on listen (user_id, song_id, timestamp desc);
create index idx_listen_user_timestamp on listen (user_id, timestamp desc);
create index idx_playlist_entry_playlist_position on playlist_entry (playlist_id, position);
alter table if exists listen add constraint fk_listen_song foreign key (song_id) references song;
alter table if exists listen add constraint fk_listen_user foreign key (user_id) references app_user;
alter table if exists playlist add constraint fk_playlist_creator foreign key (creator_id) references app_user;
alter table if exists playlist_entry add constraint fk_playlist_entry_playlist foreign key (playlist_id) references playlist;
alter table if exists playlist_like add constraint fk_playlist_like_playlist foreign key (playlist_id) references playlist;
alter table if exists playlist_like add constraint fk_playlist_like_user foreign key (user_id) references app_user;
alter table if exists song_like add constraint fk_song_like_song foreign key (song_id) references song;
alter table if exists song_like add constraint fk_song_like_user foreign key (user_id) references app_user;
